  `};window.buscarClienteNuevoCarrito=function(e){const t=window._carritoClientes||[],o=document.getElementById("nc-cliente-resultados");if(!o)return;const a=e.trim().toLowerCase();if(!a){o.style.display="none",o.innerHTML="";return}const n=t.filter(r=>(r.nombre||"").toLowerCase().includes(a)||(r.telefono||"").includes(a)).slice(0,30);if(!n.length){o.innerHTML='<div style="padding:10px;font-size:0.82rem;color:#888">Sin resultados</div>',o.style.display="block";return}o.innerHTML=n.map(r=>`
